// patch-declarations.js
// Creates dist/types/p5-augment.d.ts — the consumer-facing entry point for
// p5.mapper TypeScript types. It re-exports everything from the auto-generated
// ProjectionMapper.d.ts and adds a `declare module "p5"` augmentation so that
// TypeScript consumers using p5 v2 (where p5 is a module, not a global class)
// get proper types for the methods injected onto the p5 instance.
//
// Why a separate file instead of patching ProjectionMapper.d.ts directly?
// A `declare module "p5" { ... }` block inside ProjectionMapper.d.ts would
// need to import its own return type via import("./ProjectionMapper").default,
// which is a circular reference TypeScript can't resolve. A sibling file can
// import pMapper and use `typeof pMapper` cleanly.

const fs = require("fs");
const path = require("path");

const outDir = path.resolve(__dirname, "../dist/types");
const target = path.join(outDir, "p5-augment.d.ts");

const content = `// Auto-generated by scripts/patch-declarations.js — do not edit manually.
// Consumer-facing TypeScript entry point for p5.mapper.

// Re-export the pMapper singleton (default) and all named types.
export { default } from "./ProjectionMapper";
export * from "./ProjectionMapper";

import type pMapper from "./ProjectionMapper";

// ---- p5 v2 module augmentation ----
// Consumers who side-effect-import p5.mapper get these instance methods typed:
//   import 'p5.mapper';
declare module "p5" {
  interface p5 {
    createProjectionMapper(pInst: any, w?: number, h?: number): typeof pMapper;
    isCalibratingMapper(): boolean;
    isMovingPoints(): boolean;
    isDragging(surface: any): boolean;
    initPMapperShader(): void;
  }
}
`;

fs.writeFileSync(target, content, "utf8");
console.log("patch-declarations: wrote", target);
